--
-- Name: enforce_data_source_provider_message_cap(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_data_source_provider_message_cap() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    DELETE FROM data_source_provider_messages
    WHERE data_source_id = NEW.data_source_id
      AND id IN (
          SELECT id
          FROM data_source_provider_messages
          WHERE data_source_id = NEW.data_source_id
          ORDER BY occurred_at DESC, id DESC
          OFFSET 1001
      );
    RETURN NEW;
END;
$$;


--
-- Name: measurements_no_overlap_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.measurements_no_overlap_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    stop_ts timestamptz := COALESCE(
        NEW.interval_end,
        NEW.timestamp + NEW.resolution_seconds * interval '1 second'
    );
    predecessor timestamptz;
    predecessor_stop timestamptz;
BEGIN
    SELECT m.timestamp,
           COALESCE(
               m.interval_end,
               m.timestamp + m.resolution_seconds * interval '1 second'
           )
      INTO predecessor, predecessor_stop
      FROM measurements m
     WHERE m.channel_id = NEW.channel_id
       AND m.resolution_seconds = NEW.resolution_seconds
       AND m.timestamp < stop_ts
       AND NOT (
           m.timestamp = NEW.timestamp
           AND m.resolution_seconds = NEW.resolution_seconds
       )
     ORDER BY m.timestamp DESC
     LIMIT 1;

    IF FOUND AND predecessor_stop > NEW.timestamp THEN
        RAISE EXCEPTION 'overlapping measurement interval (channel %, resolution %, timestamp %)',
            NEW.channel_id, NEW.resolution_seconds, NEW.timestamp
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END $$;


--
-- Name: revoke_persistent_state_on_provider_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revoke_persistent_state_on_provider_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.provider_type IS DISTINCT FROM NEW.provider_type THEN
        DELETE FROM data_source_persistent_state WHERE data_source_id = NEW.id;
    END IF;
    RETURN NEW;
END;
$$;


